callGraph.callee:
characterStateService.create({
                novelId, characterId: cc.characterId, chapterId: chapter.id,
                stateSummary: cc.stateSummary, relationshipChanges: cc.relationshipChanges,
                goalChanges: cc.goalChanges, location: cc.location,
                healthState: cc.healthState, knowledgeState: cc.knowledgeState,
              }).catch

result.relationshipChanges.map((item: any) => ({
      fromCharacterName: String(item.fromCharacterName || item.from || ''),
      toCharacterName: String(item.toCharacterName || item.to || ''),
      change: String(item.change || ''),
    })).filter

result.contextRecords.map((item: any) => ({
      contextType: normalizeContextType(item.contextType),
      title: String(item.title || '上下文记录'),
      content: String(item.content || ''),
      importance: normalizeImportance(item.importance),
    })).filter

input.chapterContexts.map((ctx, i) => {
      const parts = [
        `第${i + 1}章：${ctx.chapterTitle}`,
        `摘要：${ctx.summary}`,
        ctx.keyEvents.length > 0 ? `关键事件：${ctx.keyEvents.join('；')}` : '',
        ctx.protagonistStateChange ? `主角变化：${ctx.protagonistStateChange}` : '',
        ctx.settingChanges?.length ? `设定变化：${ctx.settingChanges.join('；')}` : '',
        ctx.unresolvedQuestions?.length ? `未解决问题：${ctx.unresolvedQuestions.join('；')}` : '',
        ctx.factsMustRemember?.length ? `必须记住的事实：${ctx.factsMustRemember.join('；')}` : '',
      ];
      return parts.filter(Boolean).join('\n');
    }).join
